const getMediaOperationGrantIDs = `-- name: GetMediaOperationGrantIDs :many
SELECT grant_id FROM rtc_media_operation_targets WHERE operation_id=$1 ORDER BY grant_id
`

func (q *Queries) GetMediaOperationGrantIDs(ctx context.Context, operationID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, getMediaOperationGrantIDs, operationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var grant_id uuid.UUID
		if err := rows.Scan(&grant_id); err != nil {
			return nil, err
		}
		items = append(items, grant_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

